35: struct AVxWorkerImpl {
36:   pthread_mutex_t mutex_;
37:   pthread_cond_t condition_;
38:   pthread_t thread_;
39: };
40: 
41: //------------------------------------------------------------------------------
42: 
43: static void execute(AVxWorker *const worker);  // Forward declaration.
