110:       pthread_cond_wait(&worker->impl_->condition_, &worker->impl_->mutex_);
111:     }
112:     // assign new status and release the working thread if needed
113:     if (new_status != AVX_WORKER_STATUS_OK) {
114:       worker->status_ = new_status;
115:       pthread_cond_signal(&worker->impl_->condition_);
116:     }
117:   }
118:   pthread_mutex_unlock(&worker->impl_->mutex_);
119: }
