125: static void init(AVxWorker *const worker) {
126:   memset(worker, 0, sizeof(*worker));
127:   worker->status_ = AVX_WORKER_STATUS_NOT_OK;
128: }
129: 
130: static int sync(AVxWorker *const worker) {
131: #if CONFIG_MULTITHREAD
132:   change_state(worker, AVX_WORKER_STATUS_OK);
133: #endif
134:   assert(worker->status_ <= AVX_WORKER_STATUS_OK);
135:   return !worker->had_error;
136: }
137: 
138: static int reset(AVxWorker *const worker) {
139:   int ok = 1;
140:   worker->had_error = 0;
141:   if (worker->status_ < AVX_WORKER_STATUS_OK) {
142: #if CONFIG_MULTITHREAD
143:     worker->impl_ = (AVxWorkerImpl *)aom_calloc(1, sizeof(*worker->impl_));
