169:         pthread_attr_destroy(&attr);
170:         goto Error2;
171:       }
172:     }
173:     pthread_mutex_lock(&worker->impl_->mutex_);
174:     ok = !pthread_create(&worker->impl_->thread_, &attr, thread_loop, worker);
175:     if (ok) worker->status_ = AVX_WORKER_STATUS_OK;
176:     pthread_mutex_unlock(&worker->impl_->mutex_);
