211: static void end(AVxWorker *const worker) {
212: #if CONFIG_MULTITHREAD
213:   if (worker->impl_ != NULL) {
214:     change_state(worker, AVX_WORKER_STATUS_NOT_OK);
215:     pthread_join(worker->impl_->thread_, NULL);
216:     pthread_mutex_destroy(&worker->impl_->mutex_);
217:     pthread_cond_destroy(&worker->impl_->condition_);
218:     aom_free(worker->impl_);
219:     worker->impl_ = NULL;
220:   }
221: #else
222:   worker->status_ = AVX_WORKER_STATUS_NOT_OK;
223:   assert(worker->impl_ == NULL);
224: #endif
225:   assert(worker->status_ == AVX_WORKER_STATUS_NOT_OK);
226: }
